import sys
from collections import defaultdict

def solve():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    t = data[idx]
    idx += 1
    ans_list = []

    for _ in range(t):
        n = data[idx]
        idx += 1
        a = data[idx:idx + 2 * n]
        idx += 2 * n

        adjacent_pairs = defaultdict(list)

        for i in range(2 * n - 1):
            x, y = a[i], a[i + 1]
            if x == y:
                continue
            if x > y:
                x, y = y, x
            adjacent_pairs[(x, y)].append(i)

        ans = 0

        for starts in adjacent_pairs.values():
            m = len(starts)
            found = False

            for i in range(m):
                for j in range(i + 1, m):
                    left = starts[i]
                    right = starts[j]
                    gap = right - left

                    if gap == 1:
                        continue

                    if gap == 2 and a[left] != a[right]:
                        continue

                    found = True
                    break

                if found:
                    break

            if found:
                ans += 1

        ans_list.append(str(ans))

    sys.stdout.write("\n".join(ans_list))

if __name__ == "__main__":
    solve()
